use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The handle's allowlist, mirrored here so that a URL outside it is recorded
/// as a failure instead of reaching the boundary, where it would trap and
/// abort the whole run. The host still enforces the allowlist; this check
/// only keeps one bad subscription from killing the batch.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extracts the host of an http(s) URL, failing closed on anything ambiguous.
/// Whitespace, control characters, and backslashes are rejected outright,
/// since WHATWG URL parsing normalises some of them in ways that could move
/// the host.
fn host_of(url: &str) -> Option<String> {
    if url.bytes().any(|b| b <= b' ' || b == b'\\' || b == 0x7f) {
        return None;
    }
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let end = rest.find(|c: char| matches!(c, '/' | '?' | '#')).unwrap_or(rest.len());
    let authority = &rest[..end];
    // Userinfo ends at the last '@' in the authority.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    if host_port.starts_with('[') {
        return None;
    }
    let host = match host_port.find(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };
    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            let allowed = host_of(&url)
                .map_or(false, |h| ALLOWED_HOSTS.contains(&h.as_str()));
            if !allowed {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
